-- MP-0055: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'MP-0055: missing party parent'; end if; if exists(select 1 from public.entities where slug='pbs' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='gabungan-rakyat-sabah'))) then raise exception 'MP-0055: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'pbs','Parti Bersatu Sabah','PBS','government','A component party of Gabungan Rakyat Sabah (GRS).','2026-11-10','[{"label": "PBS · current leadership and GRS cooperation, September 2026", "url": "https://www.thestar.com.my/news/nation/2026/09/27/joachim-officially-takes-helm-of-pbs"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='barisan-nasional' and type='alliance') then raise exception 'MP-0055: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pbs' and type='party') then raise exception 'MP-0055: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='warisan' and type='party') then raise exception 'MP-0055: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('mohd-shafie-apdal','lo-su-fui','andi-muhammad-suryady-bandy') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0055: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('semporna','tawau','kalabakan') and slug not in ('mohd-shafie-apdal','lo-su-fui','andi-muhammad-suryady-bandy')) then raise exception 'MP-0055: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0055:%' and (m.source_type <> 'editorial' or e.slug not in ('mohd-shafie-apdal','lo-su-fui','andi-muhammad-suryady-bandy') or m.import_key not like 'MP-0055:' || e.slug || ':%')) then raise exception 'MP-0055: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-shafie-apdal','Mohd Shafie Apdal','government','Member of the Dewan Rakyat; President of WARISAN','Semporna','Sabah','Mohd Shafie Apdal represents Semporna, Sabah, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; President of WARISAN. Affiliated with WARISAN.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4228','/portraits/mohd-shafie-apdal.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P189.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4228"}, {"label": "WARISAN · current president, 25 October 2026", "url": "https://www.utusanborneo.com.my/2026/10/25/shafie-tidak-tolak-campur-tangan-luar-dalam-pemilihan-warisan"}, {"label": "WARISAN · federal-government support, 3 August 2026", "url": "https://www.bernama.com/en/news.php?id=2589775"}]'::jsonb from public.entities parent where parent.slug='warisan' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'lo-su-fui','Lo Su Fui','government','Deputy Minister in the Prime Minister’s Department (Federal Territories); Deputy President of PBS','Tawau','Sabah','Lo Su Fui represents Tawau, Sabah, in the Dewan Rakyat. Current role: Deputy Minister in the Prime Minister’s Department (Federal Territories); Deputy President of PBS. Affiliated with PBS.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4229','/portraits/lo-su-fui.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/tawau%20P190.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4229"}, {"label": "PBS · current deputy president and GRS cooperation, 27 September 2026", "url": "https://www.thestar.com.my/news/nation/2026/09/27/joachim-officially-takes-helm-of-pbs"}]'::jsonb from public.entities parent where parent.slug='pbs' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'andi-muhammad-suryady-bandy','Andi Muhammad Suryady Bandy','government','Member of the Dewan Rakyat','Kalabakan','Sabah','Andi Muhammad Suryady Bandy represents Kalabakan, Sabah, in the Dewan Rakyat. Parliament records affiliation with Barisan Nasional (BN). Reports of suspended UMNO membership are recorded in the profile sources.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4230','/portraits/andi-muhammad-suryady-bandy.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P191.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4230"}, {"label": "UMNO membership suspension · 17 March 2026", "url": "https://www.dailyexpress.com.my/news/277915/kalabakan-umno-opens-doors-to-former-suspended-members"}]'::jsonb from public.entities parent where parent.slug='barisan-nasional' and parent.type='alliance' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('mohd-shafie-apdal','lo-su-fui','andi-muhammad-suryady-bandy') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0055: concurrent ownership or identity change'; end if; end $$;

commit;
